%   returns f: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    f = 0;
    rho = (6378137 / r);
    h__16 = beta;
    if h__16 < 0, h__16 = -h__16; elseif h__16 == 0, h__16 = 0; end
    h__17 = asin(rho);
    if ~isreal(h__17), h__17 = NaN; end
